import { normalizeMembership } from '../lib/notes'
import { sortNotes } from '../lib/selectors'
import { INBOX_ID, createFreshWorkspace } from '../persistence/format'
import type {
  AppState,
  MobilePane,
  Note,
  Notebook,
  NotebookColorKey,
} from '../types'

/**
 * Actions understood by the workspace reducer.
 *
 * The reducer is pure: ids and timestamps are generated by the caller and
 * carried in the action, so the same input always produces the same state and
 * the CRUD rules can be tested without a browser.
 */
export type WorkspaceAction =
  | { type: 'hydrate'; notes: Note[]; notebooks: Notebook[] }
  | { type: 'select-note'; id: string | null }
  | { type: 'select-notebook'; id: string | null }
  | { type: 'set-search'; query: string }
  | { type: 'set-drawer'; open: boolean }
  | { type: 'set-mobile-pane'; pane: MobilePane }
  // --- notes ---
  | { type: 'create-note'; note: Note }
  | { type: 'rename-note'; id: string; title: string; now: number }
  | { type: 'delete-note'; id: string }
  | { type: 'toggle-pin'; id: string }
  | { type: 'set-note-notebooks'; id: string; notebookIds: string[]; now: number }
  | { type: 'set-note-content'; id: string; content: string; now: number }
  // --- notebooks ---
  | { type: 'create-notebook'; notebook: Notebook }
  | { type: 'rename-notebook'; id: string; name: string }
  | { type: 'set-notebook-color'; id: string; color: NotebookColorKey }
  | { type: 'delete-notebook'; id: string }

/**
 * Starting state: a new workspace with an Inbox and no notes.
 *
 * Nothing is fabricated here. Before a directory is connected the app holds an
 * empty workspace in memory and says so; the only way notes appear is by
 * creating them or by reading them from the chosen directory.
 */
export function createInitialState(): AppState {
  const { notes, notebooks } = createFreshWorkspace()

  return {
    notes,
    notebooks,
    activeNoteId: null,
    // `null` means "All notes", which is the default lens.
    activeNotebookId: null,
    searchQuery: '',
    drawerOpen: false,
    mobilePane: 'list',
  }
}

/** Keep the selection valid after the note list is replaced wholesale. */
function pickActiveNote(notes: readonly Note[], currentId: string | null): string | null {
  if (currentId && notes.some((note) => note.id === currentId)) return currentId
  const ordered = sortNotes(notes)
  return ordered[0]?.id ?? null
}

/**
 * The note to select after a deletion: the one that took the deleted note's
 * place in the list, so the list does not jump back to the top.
 */
function neighbourAfterDelete(
  notes: readonly Note[],
  deletedId: string,
): string | null {
  const ordered = sortNotes(notes)
  const index = ordered.findIndex((note) => note.id === deletedId)
  const remaining = ordered.filter((note) => note.id !== deletedId)
  if (remaining.length === 0) return null
  return remaining[Math.min(index, remaining.length - 1)].id
}

function updateNote(
  state: AppState,
  id: string,
  change: (note: Note) => Note,
): AppState {
  return {
    ...state,
    notes: state.notes.map((note) => (note.id === id ? change(note) : note)),
  }
}

export function workspaceReducer(
  state: AppState,
  action: WorkspaceAction,
): AppState {
  switch (action.type) {
    case 'hydrate': {
      return {
        ...state,
        notes: action.notes,
        notebooks: action.notebooks,
        activeNoteId: pickActiveNote(action.notes, state.activeNoteId),
        activeNotebookId: state.notebooks.some(
          (nb) => nb.id === state.activeNotebookId,
        )
          ? state.activeNotebookId
          : null,
      }
    }

    case 'select-note':
      return {
        ...state,
        activeNoteId: action.id,
        // Selecting a note on mobile moves to the editor pane; at desktop
        // widths `mobilePane` is ignored by the layout.
        mobilePane: action.id ? 'editor' : 'list',
        drawerOpen: false,
      }

    case 'select-notebook':
      return { ...state, activeNotebookId: action.id, drawerOpen: false }

    case 'set-search':
      return { ...state, searchQuery: action.query }

    case 'set-drawer':
      return { ...state, drawerOpen: action.open }

    case 'set-mobile-pane':
      return { ...state, mobilePane: action.pane }

    case 'create-note':
      return {
        ...state,
        notes: [action.note, ...state.notes],
        activeNoteId: action.note.id,
        mobilePane: 'editor',
        // A new note has no text yet, so an active query would hide it and the
        // user would appear to have created nothing.
        searchQuery: '',
      }

    case 'rename-note':
      return updateNote(state, action.id, (note) => ({
        ...note,
        title: action.title,
        updatedAt: action.now,
      }))

    case 'delete-note': {
      const notes = state.notes.filter((note) => note.id !== action.id)
      const wasActive = state.activeNoteId === action.id
      const activeNoteId = wasActive
        ? neighbourAfterDelete(state.notes, action.id)
        : state.activeNoteId
      return {
        ...state,
        notes,
        activeNoteId,
        mobilePane: activeNoteId ? state.mobilePane : 'list',
      }
    }

    case 'toggle-pin':
      // Deliberately does not touch `updatedAt`: pinning changes where a note
      // sits in the list, it is not an edit to the note itself.
      return updateNote(state, action.id, (note) => ({
        ...note,
        pinned: !note.pinned,
      }))

    case 'set-note-notebooks':
      return updateNote(state, action.id, (note) => ({
        ...note,
        notebookIds: normalizeMembership(
          action.notebookIds,
          state.notebooks.map((nb) => nb.id),
        ),
        updatedAt: action.now,
      }))

    case 'set-note-content':
      // Deliberately leaves `versions` alone. PROJECT_PLAN.md §6 forbids a new
      // snapshot per keystroke, and history is Phase 6 — Phase 4 only edits the
      // live content.
      return updateNote(state, action.id, (note) => ({
        ...note,
        content: action.content,
        updatedAt: action.now,
      }))

    case 'create-notebook':
      return {
        ...state,
        notebooks: [...state.notebooks, action.notebook],
        activeNotebookId: action.notebook.id,
        drawerOpen: false,
      }

    case 'rename-notebook':
      return {
        ...state,
        notebooks: state.notebooks.map((nb) =>
          nb.id === action.id ? { ...nb, name: action.name } : nb,
        ),
      }

    case 'set-notebook-color':
      return {
        ...state,
        notebooks: state.notebooks.map((nb) =>
          nb.id === action.id ? { ...nb, color: action.color } : nb,
        ),
      }

    case 'delete-notebook': {
      // Inbox is the destination for every unfiled note, so it cannot be
      // removed; the UI does not offer the control for it.
      if (action.id === INBOX_ID) return state

      const notebooks = state.notebooks.filter((nb) => nb.id !== action.id)
      const known = notebooks.map((nb) => nb.id)

      return {
        ...state,
        notebooks,
        // Notes that were only in the deleted notebook fall back to Inbox
        // rather than becoming unreachable.
        notes: state.notes.map((note) =>
          note.notebookIds.includes(action.id)
            ? { ...note, notebookIds: normalizeMembership(note.notebookIds, known) }
            : note,
        ),
        activeNotebookId:
          state.activeNotebookId === action.id ? null : state.activeNotebookId,
      }
    }

    default:
      return state
  }
}
